לא. עִקַּר הַהִתְחַזְּקוּת לְהִתְחַזֵּק בְּהַשֵּׁם יִתְבָּרַךְ תָּמִיד עַל־יְדֵי בְּחִינַת 'מְלֹא כָל הָאָרֶץ כְּבוֹדוֹ' (כַּמְבֹאָר בְּמָקוֹם אַחֵר), הוּא עַל־יְדֵי דִּבּוּר־פֶּה, הַיְנוּ עַל־יְדֵי שִׂיחָה וּתְפִלָּה וְהִתְבּוֹדְדוּת וְכוּ' (הל' שותפים בקרקע, הל' ה, בראשי פרקים). 
לב. עִקַּר הַתְּשׁוּבָה הוּא תְּפִלָּה. כִּי תְּשׁוּבָה הוּא בְּחִינַת לְמַעְלָה מֵהַתּוֹרָה, שֶׁשָּׁם נִתְהַפֵּךְ הַכֹּל לְטוֹבָה וּזְדוֹנוֹת נִתְהַפְּכִין לִזְכֻיּוֹת. וְלָזֶה זוֹכִין עַל־יְדֵי תְּפִלָּה, כִּי תְּפִלָּה הוּא גַּם־כֵּן בְּחִינַת לְמַעְלָה מֵהַתּוֹרָה, כַּמְבֹאָר בִּפְנִים. וְעַל־כֵּן מִי שֶׁרוֹצֶה לָשׁוּב לְהַשֵּׁם יִתְבָּרַךְ בֶּאֱמֶת, עִקַּר הַתְּשׁוּבָה שְׁלֵמָה הוּא עַל־יְדֵי תְּפִלָּה, דְּהַיְנוּ שֶׁיִּתְפַּלֵּל תָּמִיד לְהַשֵּׁם יִתְבָּרַךְ שֶׁיִּמְחַל וְיִסְלַח לוֹ עַל מַה שֶּׁפָּגַם, וִירַחֵם עָלָיו מֵעַתָּה וְיַצִּילֵהוּ מֵעֲו?ֹנוֹת. כִּי בֶּאֱמֶת כָּל אָדָם הוּא בְּסַכָּנָה גְדוֹלָה וַעֲצוּמָה בְּזֶה הָעוֹלָם, וּבִפְרָט הַבַּעַל־ תְּשׁוּבָה, שֶׁכְּבָר נִכְשַׁל בַּמֶּה שֶׁנִּכְשַׁל, וּבְכָל יוֹם יִצְרוֹ מִתְגַּבֵּר עָלָיו וְכוּ', וְאֵיךְ יִזְכֶּה לָשׁוּב? כִּי תֵּכֶף כְּשֶׁרוֹצֶה לְהִתְגַּבֵּר עַל מַה שֶּׁצָּרִיךְ לְהִתְגַּבֵּר, מִתְגַּבְּרִין עָלָיו בְּיוֹתֵר. עַל־כֵּן הָעִקָּר הוּא תְּפִלָּה וְהִתְבּוֹדְדוּת, שֶׁצָּרִיךְ לְהַרְגִּיל אֶת עַצְמוֹ לְהִתְבּוֹדֵד בְּכָל יוֹם בֵּינוֹ לְבֵין קוֹנוֹ וּלְהַפִּיל תְּחִנָּתוֹ לִפְנֵי הַשֵּׁם יִתְבָּרַךְ הַמָּלֵא רַחֲמִים בְּכָל עֵת, שֶׁיְּזַכֵּהוּ לָשׁוּב בִּתְשׁוּבָה שְׁלֵמָה בֶּאֱמֶת; וַאֲפִלּוּ אִם רוֹאֶה שֶׁאֵינוֹ פּוֹעֵל עֲדַיִן בִּתְפִלָּתוֹ, כִּי עֲדַיִן מִתְגַּבְּרִין עָלָיו בְּיוֹתֵר, אַף־עַל־פִּי־כֵן יַעֲשֶׂה אֶת שֶׁלּוֹ וְיִתְפַּלֵּל תָּמִיד לְהַשֵּׁם יִתְבָּרַךְ, אוּלַי יָחוּס, אוּלַי יְרַחֵם, כְּמוֹ שֶׁכָּתוּב: "קַוֵּה אֶל ה' וְכוּ'", וְאָמְרוּ רַבּוֹתֵינוּ זַ"ל: וְאִם לֹא נִתְקַבְּלָה תְּפִלָּתְךָ, חֲזֹר וְקַוֵּה. וְכָל זְמַן שֶׁאֵין הָאָדָם חָזָק בְּדַעְתּוֹ שֶׁתָּמִיד יְקַוֶּה לַה' וְיַעְתִּיר אֵלָיו אַף אִם יַעֲבֹר עָלָיו מָה, עֲדַיִן אֵין תְּשׁוּבָתוֹ שְׁלֵמָה, כִּי מִי יוֹדֵעַ מַה יֵּלֶד יוֹם, אוּלַי יָבוֹא עָלָיו נִסָּיוֹן אוֹ מִכְשׁוֹל וְכוּ', וּמִי יוֹדֵעַ אִם יַעֲמֹד בְּקִשְׁרֵי הַמִּלְחָמָה. אֲבָל אִם הָאָדָם חָזָק בְּדַעְתּוֹ, שֶׁאֲפִלּוּ אִם, חַס וְשָׁלוֹם, לֹא יַעֲמֹד בְּנִסָּיוֹן, וַאֲפִלּוּ אִם יִהְיֶה, חַס וְשָׁלוֹם, אֵיךְ שֶׁיִּהְיֶה - אַף־עַל־פִּי־כֵן יְקַוֶּה תָּמִיד לְהַשֵּׁם יִתְבָּרַךְ, בִּבְחִינַת "וְאַצִּיעָה שְּׁאוֹל הִנֶּךָֹּ", אֲזַי הוּא בָּטוּחַ שֶׁבְּוַדַּאי יִזְכֶּה לִתְשׁוּבָה שְׁלֵמָה, כִּי סוֹף כָּל סוֹף יָשׁוּב לְהַשֵּׁם יִתְבָּרַךְ, מֵאַחַר שֶׁחָזָק בְּדַעְתּוֹ שֶׁלֹּא יִפֹּל מִשּׁוּם

