ג. צָרִיךְ כָּל אָדָם לֵידַע, שֶׁבְּכָל עֵת שֶׁמִּתְנוֹצֵץ לוֹ אֵיזֶה הִתְנוֹצְצוּת אֱלָקוּת, אוֹ אִם נִתְעוֹרֵר בְּאֵיזֶה הִתְעוֹרְרוּת חָדָשׁ לְהַשֵּׁם יִתְבָּרַךְ, אֲזַי תֵּכֶף מִתְגָּרִים בּוֹ יוֹתֵר וְיוֹתֵר, וְצָרִיךְ לִהְיוֹת חָזָק הַרְבֵּה לְבַל יִפֹּל מִזֶּה וְאַל יֶחֱלַשׁ דַּעְתּוֹ עַל־יְדֵי זֶה, אֲפִלּוּ אִם יִהְיֶה כֵּן אֲלָפִים וְרִבְבוֹת פְּעָמִים, חַס וְשָׁלוֹם, רַק צָרִיךְ לְהִתְחַזֵּק הַרְבֵּה עַל־יְדֵי הַתּוֹרָה, הַיְנוּ שֶׁיִּתְחַזֵּק לְהַמְשִׁיךְ חִדּוּשֵׁי־ תוֹרָה אֲמִתִּיִּים. וַאֲפִלּוּ מִי שֶׁאֵינוֹ זוֹכֶה לָזֶה, יְחַזֵּק אֶת עַצְמוֹ עַל־כָּל־פָּנִים לַעֲסֹק בַּתּוֹרָה בְּהִתְעוֹרְרוּת חָדָשׁ וּלְקַיֵּם אֶת כָּל דִּבְרֵי הַתּוֹרָה בִּפְשִׁיטוּת וּתְמִימוּת, וְלֹא יֵצֵא מִדַּרְכֵי הַתּוֹרָה, חַס וְשָׁלוֹם. כִּי אַף־עַל־פִּי שֶׁלְּפִי אוֹר הִתְלַהֲבוּת לְבָבוֹ הוּא נִכְסָף לִהְיוֹת קָדוֹשׁ וּפָרוּשׁ וּמֻבְדָּל לְגַמְרֵי מֵהַבְלֵי עוֹלָם הַזֶּה, לְפִי הַזְּרִיחָה שֶׁל הַהִתְנוֹצְצוּת הַזֶּה, וּבֶאֱמֶת כָּךְ רָאוּי לִהְיוֹת; אַךְ אִם אַף־עַל־פִּי־כֵן יִצְרוֹ מִתְגַּבֵּר עָלָיו וּמִתְגָּרֶה בּוֹ עַתָּה בְּיוֹתֵר דַּיְקָא, אַל יִפֹּל לְגַמְרֵי עַל־יְדֵי זֶה, חַס וְשָׁלוֹם, רַק יִתְחַזֵּק לִבְלִי לָצֵאת עַל־כָּל־פָּנִים מִדַּרְכֵי הַתּוֹרָה בִּפְשִׁיטוּת, וִיקַיֵּם מִקְרָא שֶׁכָּתוּב: "אַל תִּצְדַּק הַרְבֵּה, וְאַל תִּרְשַׁע הַרְבֵּה", שֶׁלֹּא יִרְשַׁע הַרְבֵּה, חַס וְשָׁלוֹם, עַל־יְדֵי שֶׁרָצָה לִצְדֹּק הַרְבֵּה וְלֹא עָלְתָה בְּיָדוֹ. וְאָז כְּשֶׁיֵּלֵךְ בְּדֶרֶךְ זֶה וְיִהְיֶה חָזָק בָּזֶה הַרְבֵּה, אָז יֵלֵךְ לָבֶטַח דַּרְכּוֹ וְיוּכַל בְּכָל פַּעַם לְעוֹרֵר אֶת עַצְמוֹ לְהַשֵּׁם יִתְבָּרַךְ, וְלִסְתֹּם עֵינָיו בְּכָל עֵת מֵחֵזוּ דְּהַאי עָלְמָא, וּלְבַטֵּל עַצְמוֹ אֵלָיו יִתְבָּרַךְ. וְאִם יִזְכֶּה לְבַטֵּל אֶת עַצְמוֹ בֶּאֱמֶת מֵעַתָּה, לָצֵאת מֵחֵזוּ דְּהַאי עָלְמָא לְגַמְרֵי כָּרָאוּי בֶּאֱמֶת - בְּוַדַּאי מַה טּוֹב; וְאִם לָאו, חַס וְשָׁלוֹם - עַל־כָּל־פָּנִים לֹא יִפֹּל מִזֶּה כְּלָל וּכְלָל, רַק יְחַזֵּק אֶת עַצְמוֹ לִהְיוֹת אִישׁ כָּשֵׁר בִּפְשִׁיטוּת גָּמוּר עַל־פִּי דַּרְכֵי הַתּוֹרָה הַקְּדוֹשָׁה, כִּי הַתּוֹרָה מְשַׁבֶּרֶת וּמְבַטֶּלֶת כָּל הַסִּטְרָא־אָחֳרָא הָרוֹצִים לְהִתְגָּרוֹת בָּנוּ, חַס וְשָׁלוֹם (שם טז). 
ד. מִי שֶׁרוֹצֶה לְהִתְקָרֵב לְהַשֵּׁם יִתְבָּרַךְ, צָרִיךְ תָּמִיד לְבַקֵּשׁ אֶת הַשֵּׁם בְּכָל מָקוֹם אֲשֶׁר הוּא שָׁם, וּלְקַשֵּׁר וּלְהַעֲלוֹת בְּחִינַת הַמָּקוֹם אֲשֶׁר הוּא שָׁם לִבְחִינַת לְמַעְלָה מֵהַמָּקוֹם, דְּהַיְנוּ לְהַשֵּׁם יִתְבָּרַךְ שֶׁהוּא מְקוֹמוֹ שֶׁל עוֹלָם, וְאָז זוֹכֶה לַעֲבֹד אֶת הַשֵּׁם בֶּאֱמֶת וְאֵין שׁוּם מָקוֹם שֶׁיִּמְנָעֵהוּ. וַאֲפִלּוּ מִי שֶׁנָּפַל לְאֵיזֶה מָקוֹם לֹא טוֹב בַּחֲטָאָיו, וַאֲפִלּוּ לְמָקוֹם נָמוּךְ וּמְגֻשָּׁם וּמְלֻכְלָךְ מְאֹד, חַס וְשָׁלוֹם, רַחֲמָנָא לִצְּלַן, אַף־עַל־פִּי־כֵן צָרִיךְ שֶׁיִּזְכֹּר בְּהַשֵּׁם יִתְבָּרַךְ, שֶׁהוּא מְקוֹמוֹ שֶׁל עוֹלָם, שֶׁשָּׁם יֵשׁ מָקוֹם לְכָל אֶחָד וְאֶחָד. וְעַל־כֵּן אֵין שׁוּם נְפִילָה בָּעוֹלָם כְּלָל, כִּי מִכָּל הַמְּקוֹמוֹת אֲשֶׁר נִדַּח לְשָׁם יָכוֹל לַחֲזֹר לְהַשֵּׁם יִתְבָּרַךְ, בִּבְחִינַת "וּבִקַּשְׁתֶּם מִשָּׁם אֶת ה' אֱלֹקֶיךָ" - מִשָּׁם דַּיְקָא, מִמָּקוֹם אֲשֶׁר

). 
כז. כְּשֶׁהָאָדָם עוֹלֶה מִדַּרְגָּא לְדַרְגָּא בַּעֲבוֹדַת הַשֵּׁם, זֶה בְּחִינַת בְּרִיאָה חֲדָשָׁה, כִּי נַעֲשֶׂה בְּרִיָּה חֲדָשָׁה מַמָּשׁ, בִּבְחִינַת "אֲנִי הַיּוֹם יְלִדְתִּיךָ", הַנֶּאֱמָר עַל הָאָדָם כְּשֶׁנַּעֲשֶׂה בַּר־מִצְוָה, דְּהַיְנוּ בֶּן י"ג שָׁנָה שֶׁנִּתְחַיֵּב בְּמִצְו?ֹת, כַּמְבֹאָר בַּזֹּהַר הַקָּדוֹשׁ. וּכְמוֹ־כֵן הוּא בְּכָל עֵת שֶׁהָאָדָם מְקַדֵּשׁ וּמְטַהֵר עַצְמוֹ וּמְקַבֵּל עַל עַצְמוֹ עֹל עֲבוֹדַת הַשֵּׁם בְּיוֹתֵר, שֶׁאָז נֶאֱמָר עָלָיו "אֲנִי הַיּוֹם יְלִדְתִּיךָ", כִּי נַעֲשֶׂה בְּרִיאָה חֲדָשָׁה מַמָּשׁ. וְעַל־כֵּן קֹדֶם שֶׁזּוֹכֶה לָזֶה לַעֲלוֹת מִדַּרְגָּא לְדַרְגָּא שֶׁיִּהְיֶה נַעֲשֶׂה בְּרִיָּה חֲדָשָׁה, קֹדֶם לָזֶה צָרִיךְ שֶׁיִּהְיֶה יְרִידָה, שֶׁהוּא תַּכְלִית הָעֲלִיָּה, כִּי הַיְרִידָה הוּא מִבְּחִינַת הַצִּמְצוּם שֶׁל הֶחָלָל הַפָּנוּי, שֶׁהָיָה צָרִיךְ לִהְיוֹת קֹדֶם הַבְּרִיאָה כַּיָּדוּעַ. וְזֶה גַּם בְּחִינַת מַאֲמַר רַבּוֹתֵינוּ זַ"ל: צַדִּיקִים תְּחִלָּתָן יִסּוּרִין וְסוֹפָן שַׁלְוָה, כִּי הַיִּסּוּרִים בָּאִים מֵהַצִּמְצוּם שֶׁקֹּדֶם לַבְּרִיאָה. וְזֶה בְּחִינַת כָּל הַמְּנִיעוֹת וְעִכּוּבִים שֶׁיֵּשׁ לְהָאָדָם קֹדֶם שֶׁזּוֹכֶה לַעֲשׂוֹת אֵיזֶה מִצְוָה וְדָבָר שֶׁבִּקְדֻשָּׁה, כִּי בְּכָל דָּבָר שֶׁבִּקְדֻשָּׁה בּוֹרְאִים עוֹלָמוֹת כַּיָּדוּעַ, וְעַל־כֵּן צָרִיךְ שֶׁיִּהְיֶה הַצִּמְצוּם קוֹדֵם, וְזֶה בְּחִינַת הַמְּנִיעוֹת הַקּוֹדְמִין לְהַדָּבָר שֶׁבִּקְדֻשָּׁה (הלכות תפלת המנחה, הלכה ד). 
כח. בַּתְּחִלָּה כְּשֶׁאָדָם מַתְחִיל לַעֲבֹד אֶת הַשֵּׁם יִתְבָּרַךְ, וַאֲזַי הוֹלֵךְ לוֹ עַל־פִּי־ רֹב כְּסֵדֶר קְצָת, וּמִתְפַּלֵּל וְלוֹמֵד וְעוֹסֵק בַּעֲבוֹדַת הַשֵּׁם - וְזֶה בְּחִינַת שַׁחֲרִית, שֶׁהוּא בְּחִינַת חֶסֶד, וְאָז כָּל סֵדֶר הַתְּפִלָּה בַּאֲרִיכוּת, קָרְבָּנוֹת וּקְטֹרֶת וְכוּ' וּקְרִיאַת־שְׁמַע וּתְפִלָּה, וּכְמוֹ־כֵן גַּם הוּא מַרְבֶּה אָז בַּעֲבוֹדַת הַשֵּׁם, כָּל אֶחָד לְפִי בְּחִינָתוֹ; אֲבָל עַל־פִּי־רֹב אַחַר־כָּךְ נוֹפֵל מֵעֲבוֹדָתוֹ, וּמַתְחִיל הַשֵּׁם יִתְבָּרַךְ לְנַסּוֹת אוֹתוֹ, וּמִתְגָּרֶה בּוֹ הַבַּעַל־ דָּבָר, כַּיָּדוּעַ לְכָל מִי שֶׁרוֹצֶה לִכְנֹס בַּעֲבוֹדַת ה', וַאֲזַי עִקַּר הַנִּסָּיוֹן שֶׁל הָאָדָם, וַאֲזַי צְרִיכִין הִתְחַזְּקוּת גָּדוֹל מְאֹד בְּלִי שִׁעוּר וְעֵרֶךְ וּמִסְפָּר, לְהִתְחַזֵּק בְּכָל פַּעַם בַּעֲבוֹדָתוֹ יִתְבָּרַךְ וְלִבְלִי לִפֹּל מִשּׁוּם דָּבָר שֶׁבָּעוֹלָם. וְהָעִקָּר, שֶׁצָּרִיךְ לְהִתְגַּבֵּר כְּנֶגֶד בְּחִינַת הַמֹּחִין דְּקַטְנוּת, שֶׁהֵם מִתְגַּבְּרִין אָז עַל הָאָדָם וְרוֹצִין לְהַפִּילוֹ בְּדַעְתּוֹ, כְּאִלּוּ אֵין לוֹ עוֹד תִּקְוָה, חַס וְשָׁלוֹם, אוֹ לְמָנְעוֹ מִתְּפִלָּה בְּכַוָּנָה וְשִׂמְחָה וְכַיּוֹצֵא בָּזֶה. וְכָל זֶה הוּא בְּחִינַת: צָהֳרַיִם - זְמַן הַמִּנְחָה, שֶׁאָז עִקַּר אֲחִיזַת הַמֹּחִין דְּקַטְנוּת, וְצָרִיךְ לְקַיֵּם מַאֲמַר רַבּוֹתֵינוּ זַ"ל: לְעוֹלָם יְהֵא אָדָם זָהִיר בִּתְפִלַּת הַמִּנְחָה, הַיְנוּ שֶׁאָז צְרִיכִין לִזָּהֵר בְּיוֹתֵר לְהִתְחַזֵּק בִּתְפִלָּה וַעֲבוֹדַת הַשֵּׁם וְלֹא יִפֹּל מִשּׁוּם דָּבָר שֶׁבָּעוֹלָם, רַק יֵדַע וְיַאֲמִין בְּדִבְרֵי הַצַּדִּיקִים הָאֲמִתִּיִּים, שֶׁצָּעֲקוּ בְּקוֹל גָּדוֹל וְחָזָק כִּי אֵין שׁוּם יֵאוּשׁ בָּעוֹלָם כְּלָל, כִּי לִגְדֻלָּתוֹ יִתְבָּרַךְ אֵין חֵקֶר, וּבְגֹדֶל רַחֲמָיו יִתְבָּרַךְ יָכוֹל לַהֲפֹךְ הַכֹּל לְגַמְרֵי מֵרַע לְטוֹב וּמֵעֲו?ֹנוֹת לִזְכֻיּוֹת עַל־יְדֵי תְּשׁוּבָה, כְּמַאֲמַר רַבּוֹתֵינוּ זַ"ל. וּכְמוֹ־כֵן בִּכְלַל חַיֵּי הָאָדָם, שֶׁיְּמֵי חַיָּיו נִקְרָאִים יוֹם, וּמִיתָתוֹ וְהִסְתַּלְּקוּתוֹ נִקְרָא לַיְלָה וָחשֶׁךְ, כְּמוֹ שֶׁכָּתוּב: "עַד אֲשֶׁר לֹא תֶחְשַׁךְ הַשֶּׁמֶשׁ"; וְעַל־כֵּן אַחַר חֲצִי יָמָיו הוּא בְּחִינַת 'צָהֳרַיִם זְמַן הַמִּנְחָה', וְעַל־פִּי־ רֹב אָז דַּיְקָא מִתְגַּבֵּר הַבַּעַל־דָּבָר בְּיוֹתֵר וְיוֹתֵר. כִּי בְּוַדַּאי צְרִיכִין לְהַתְחִיל עִקַּר הָעֲבוֹדָה בִּימֵי הַנְּעוּרִים דַּיְקָא, כִּי 'טוֹב לַגֶּבֶר כִּי יִשָּׂא עֹל בִּנְעוּרָיו', וְ'יַנְקוּתָא - כְּלִילָא דְוַרְדָּא'; אֲבָל אֲפִלּוּ מִי שֶׁזּוֹכֶה לְהַתְחִיל בַּעֲבוֹדַת הַשֵּׁם מִנְּעוּרָיו, אַף־עַל־ פִּי־כֵן כְּשֶׁמַּגִּיעַ לְאֶמְצַע יָמָיו וְרוֹצֶה לְהַגִּיעַ לְמַה שֶּׁצָּרִיךְ לְהַגִּיעַ, אֲזַי עַל־פִּי־רֹב מִתְגַּבֵּר הַבַּעַל־דָּבָר וּמִתְפַּשֵּׁט מְאֹד לְמָנְעוֹ מִדֶּרֶךְ הַחַיִּים, חַס וְשָׁלוֹם. וּמִכָּל־שֶׁכֵּן מִי שֶׁלֹּא הִתְחִיל כְּלָל בִּימֵי נְעוּרָיו, וּכְשֶׁרוֹאֶה שֶׁעָבְרוּ רֹב שְׁנוֹתָיו, וּמְהַרְהֵר בִּתְשׁוּבָה וְרוֹצֶה לְהַתְחִיל אָז בַּעֲבוֹדַת הַשֵּׁם, שֶׁאֲזַי תֵּכֶף מִתְגַּבֵּר עָלָיו הַבַּעַל־דָּבָר וְאֵינוֹ רוֹצֶה לְהַנִּיחוֹ לָצֵאת מִתַּאֲווֹתָיו וּרִשְׁתּוֹתָיו אֲשֶׁר נִלְכַּד בָּהֶם. וְעַל זֶה צוֹעֵק הַפָּסוּק: "הַגִּידָה לִּי שֶׁאָהֲבָה נַפְשִׁי אֵיכָה תִרְעֶה אֵיכָה תַּרְבִּיץ בַּצָּהֳרָיִם" דַּיְקָא, שֶׁאָז זְמַן הַמִּנְחָה הַנַּ"ל. וְעַל־כֵּן צְרִיכִין לְהַרְבּוֹת בִּתְפִלָּה בִּימֵי הַנְּעוּרִים, שֶׁלֹּא יִפֹּל לְעוֹלָם מֵעֲבוֹדָתוֹ יִתְבָּרַךְ, כִּי לִפְעָמִים הָאָדָם נוֹפֵל לְעֵת זִקְנוּתוֹ. וּבִפְרָט כְּשֶׁכְּבָר הַיָּמִים בָּאִים וְהִגִּיעַ לְאֶמְצַע יָמָיו וּמַתְחִיל הַיּוֹם לַעֲרֹב, אָז צָרִיךְ לְהִסְתַּכֵּל בְּעַצְמוֹ מְאֹד עַל אַחֲרִיתוֹ וְסוֹפוֹ וּלְהִתְגַּבֵּר בְּיוֹתֵר וְיוֹתֵר, כִּי אָז הוּא בְּחִינַת צָהֳרַיִם, בְּחִינַת זְמַן הַמִּנְחָה, שֶׁצְּרִיכִין לִזָּהֵר בָּהּ בְּיוֹתֵר כַּנַּ"ל לְהַמְתִּיק הַדִּינִים, שֶׁהוּא בְּחִינַת הַיֵּצֶר הָרָע שֶׁאֲחִיזָתָם מִמֹּחִין דְּקַטְנוּת, בְּחִינַת זְמַן הַמִּנְחָה, וּלְקַשֵּׁר עַצְמוֹ הֵיטֵב לְצַדִּיקִים אֲמִתִּיִּים שֶׁהֵם בְּחִינַת משֶׁה, שֶׁהֵם דַּיְקָא יְכוֹלִין לְהַמְתִּיק הַדִּין שֶׁל זְמַן הַמִּנְ

). 
כט. עַיֵּן "יִרְאָה וַעֲבוֹדַת ה'", אוֹת כט, גַּם־כֵּן מֵעִנְיַן הִתְחַזְּקוּת. 
ל. מְבֹאָר בְּכִתְבֵי הָאֲרִיזַ"ל, שֶׁתְּחִלַּת הַבְּרִיאָה הָיָה עַל־יְדֵי כַּמָּה צִמְצוּמִים שֶׁכִּבְיָכוֹל הִמְשִׁיךְ הָאוֹר בְּאֵיזֶה בְּחִינָה וְאַחַר־כָּךְ הֶעֱלִימוֹ, וְכֵן כַּמָּה וְכַמָּה פְּעָמִים בְּכַמָּה דְּרָכִים, וְעַל־יְדֵי־זֶה דַּיְקָא נִתְהַוּוּ הַכֵּלִים שֶׁיּוּכְלוּ לְקַבֵּל הָאוֹר. וְכָל זֶה הוּא סוֹד מִיתַת הַמְּלָכִים וְתִקּוּנָם, שֶׁדַּיְקָא עַל־יְדֵי הַשְּׁבִירָה וְהַמִּיתָה נִמְשָׁךְ אַחַר־כָּךְ עוֹלַם הַתִּקּוּן בְּתוֹסְפוֹת אוֹר נִפְלָא יוֹתֵר, כַּמּוּבָן בַּכְּתָבִים. אֲבָל עִקַּר הַכֹּל הָיָה תָּלוּי בְּהָאָדָם הַבַּעַל־בְּחִירָה, כִּי הוּא הָיָה צָרִיךְ לְתַקֵּן הַכֹּל עַל־יְדֵי אִתְעָרוּתָא דִלְתַתָּא; וְעַל־כֵּן עַתָּה גַּם־כֵּן הָעִקָּר תָּלוּי בִּתְשׁוּבָה שֶׁל הָאָדָם, כִּי בְּהֶכְרֵחַ שֶׁיִּהְיֶה עַל־כָּל־פָּנִים אֵיזֶה הִתְעוֹרְרוּת בְּעָלְמָא, שֶׁהוּא בְּחִינַת אִתְעָרוּתָא דִלְתַתָּא. וְעַל־כֵּן אֵין לְךָ דָּבָר שֶׁעוֹמֵד בִּפְנֵי הַתְּשׁוּבָה, וְעַד יוֹם מוֹתוֹ תְּחַכֶּה לּוֹ וְכוּ', כִּי אֲפִלּוּ אִם חָטָא כְּמוֹ שֶׁחָטָא אֲלָפִים פְּעָמִים, עִם כָּל זֶה, בְּכָל פַּעַם שֶׁמִּתְעוֹרֵר בְּאֵיזֶה הִתְעוֹרְרוּת לָשׁוּב אֶל הַשֵּׁם, אֵין שׁוּם הִתְעוֹרְרוּת נֶאֱבָד, כְּמוֹ שֶׁכָּתַב בַּזֹּהַר הַקָּדוֹשׁ: לֵית רְעוּתָא טָבָא דְּאִתְאֲבִיד, כִּי עַל־יְדֵי הַתְּשׁוּבָה נִתְהַפְּכִין הָעֲו?ֹנוֹת לִזְכֻיּוֹת, כִּי נַעֲשֶׂה תִּקּוּן עַל־יְדֵי הַקִּלְקוּלִים, כִּי כָּל מַה שֶּׁקִּלְקֵל וְהִמְשִׁיךְ הָאוֹר לְמָקוֹם שֶׁהִמְשִׁיךְ, שֶׁזֶּה עִקַּר הַקִּלְקוּל; אֲבָל אַחַר־כָּךְ כְּשֶׁנִּתְעוֹרֵר בִּתְשׁוּבָה הוּא מְקַיֵּם הַכֹּל, וַאֲזַי נַעֲשֶׂה עַל־יְדֵי־זֶה דַּיְקָא כֵּלִים חֲדָשִׁים וְנִמְשָׁךְ לְתוֹכָן אוֹר חָדָשׁ וְנִפְלָא, כִּי עַל־יְדֵי שֶׁהִמְשִׁיךְ הָאוֹר לִמְקוֹמוֹת גַּסִּים וְכוּ', עַל־ יְדֵי־זֶה נִתְעַבּוּ הַכֵּלִים, וִיכוֹלִים אַחַר־כָּךְ לְזַכְּכָן עַד שֶׁיִּתְהַפֵּךְ הַכֹּל לְטוֹבָה, שֶׁדַּיְקָא עַל־יְדֵי־זֶה יִתְהַוּוּ כֵּלִים נִפְלָאִים לְקַבֵּל הָאוֹר חָדָשׁ שֶׁלֹּא הָיוּ יְכוֹלִים לְקַבֵּל מִקֹּדֶם, כִּי לֹא הָיָה אֶפְשָׁר לְהִתְעַבּוֹת הַכֵּלִים כִּי אִם עַל־יְדֵי זֶה, שֶׁזֶּהוּ בְּחִינַת 'יְרִידָה תַּכְלִית הָעֲלִיָּה', 'עֲו?ֹנוֹת נִתְהַפְּכִין לִזְכֻיּוֹת', 'הִתְרַחֲקוּת תַּכְלִית הִתְקָרְבוּת', שֶׁכָּל זֶה הוּא בְּחִינַת תִּקּוּן מִיתַת הַמְּלָכִים, שֶׁדַּיְקָא עַל־יְדֵי מִיתָתָם וּשְׁבִירָתָם נִמְשַׁךְ אוֹר־מָה הֶחָדָשׁ הַגָּדוֹל בְּיוֹתֵר, כַּמּוּבָן בַּכְּתָבִים. אֲבָל כָּל זֶה לָאו כָּל אָדָם זוֹכֶה, כִּי אִם בְּכֹחַ הַצַּדִּיקִים הַגְּדוֹלִים שֶׁיּוֹדְעִים סוֹד זֶה לְעָמְקוֹ, שֶׁהֵם יְכוֹלִים לְעוֹרֵר בְּנֵי־אָדָם לִתְשׁוּבָה וּלְחַזֵּק אֶת כָּל אֶחָד, וּלְהַעֲלוֹת כָּל מִינֵי הִתְעוֹרְרוּת בְּעָלְמָא, כָּל נְקֻדָּה וּנְקֻדָּה טוֹבָה, וּלְתַקֵּן עַל־יְדֵי־זֶה כֵּלִים נִפְלָאִים, בְּאֹפֶן שֶׁיִּתְתַּקֵּן כָּל אֶחָד בְּיֶתֶר שְׂאֵת, עַל־כֵּן צְרִיכִין לְחַפֵּשׂ מְאֹד אַחַר צַדִּיק כָּזֶה שֶׁיּוּכַל לַעֲסֹק בְּתִקּוּנוֹ, וְהַחִפּוּשׂ וְהַבַּקָּשָׁה בְּעַצְמָהּ הִיא טוֹבָה גְדוֹלָה מְאֹד לָנֶצַח אֲפִלּוּ אִם קִלְקֵל כְּמוֹ שֶׁקִּלְקֵל, כִּי הַצַּדִּיקִים הַגְּדוֹלִים זָכוּ לְמַה שֶּׁזָּכוּ עַל־יְדֵי אִתְעָרוּתָא דִלְתַתָּא שֶׁלָּהֶם בְּתַכְלִית תַּכְלִית הַשְּׁלֵמוּת, וְעַל־כֵּן עָשׂוּ כֵּלִים נִפְלָאִים וְנוֹרָאִים מְאֹד שֶׁיְּכוֹלִים לְתַקֵּן כָּל הַקִּלְקוּלִים שֶׁבָּעוֹלָם, רַחֲמָנָא לִצְּלַן. רַק אַף־עַל־פִּי־כֵן צְרִיכִין עַל־כָּל־ פָּנִים אֵיזֶה הִתְעוֹרְרוּת בְּעָלְמָא שֶׁל הָאָדָם בְּעַצְמוֹ, כִּי בְּלִי שׁוּם הִתְעוֹרְרוּת כְּלָל אִי אֶפְשָׁר לְתַקְּנוֹ כָּרָאוּי; וְיִזָּהֵר בְּנַפְשׁוֹ עַל־כָּל־ פָּנִים שֶׁלֹּא יִהְיֶה לֵץ וְחוֹלֵק עָלָיו, חַס וְשָׁלוֹם, עַל הַצַּדִּיק הָעוֹסֵק בְּתִקּוּנוֹ. וְזֶה בְּחִינַת מַעֲלַת הַתְּשׁוּבָה, שֶׁהִפְלִיגוּ בָּהּ רַבּוֹתֵינוּ זַ"ל מְאֹד, שֶׁבִּמְקוֹם שֶׁבַּעֲלֵי־ תְשׁוּבָה עוֹמְדִים וְכוּ', וְכֵן אָמְרוּ רַבּוֹתֵינוּ זַ"ל, שֶׁמַּגַּעַת עַד כִּסֵּא הַכָּבוֹד, כִּי דַּיְקָא מֵחֲמַת שֶׁיָּרַד לִמְקוֹמוֹת נְמוּכִים וּמְגֻשָּׁמִים כָּאֵלֶּה וְהִתְגַּבֵּר בְּכֹחַ הַצַּדִּיק לַעֲלוֹת מִשָּׁם, עַל־יְדֵי־זֶה דַּיְקָא נַעֲשִׂים כֵּלִים נִפְלָאִים לְקַבֵּל הָאוֹר הַנִּפְלָא, מַה שֶּׁאֵין צַדִּיקִים גְּמוּרִים יְכוֹלִים לְקַבֵּל אוֹר כָּזֶה, מֵחֲמַת שֶׁאֵין לָהֶם כֵּלִים כָּאֵלּוּ, וְכָל זֶה אִי אֶפְשָׁר לִזְכּוֹת כִּי אִם בְּכֹחַ הַצַּדִּיקִים הַגְּדוֹלִים שֶׁהֵם עִקַּר הַבַּעֲלֵי־תְשׁוּבָה, כִּי הֵם הַבְּעָלִים שֶׁל תְּשׁוּבָה, וְכָל מִי שֶׁחָס עַל חַיָּיו וְרוֹצֶה לָשׁוּב בִּתְשׁוּבָה צָרִיךְ לְקַבֵּל מֵהֶם, כִּי הֵם, אַף־עַל־ פִּי שֶׁלֹּא טָעֲמוּ טַעַם חֵטְא מֵעוֹלָם, אַף־עַל־ פִּי־כֵן הֵם עוֹשִׂים תְּשׁוּבָה בְּכָל פַּעַם עַל הַשָּׂגָתָם הָרִאשׁוֹנָה, וְגַם הֵם יוֹרְדִים לִמְקוֹמוֹת נְמוּכִים מְאֹד בְּכַוָּנָה בִּשְׁבִיל לְהַעֲלוֹת הַנְּפָשׁוֹת מִשָּׁם וּלְהַחֲזִירָם בִּתְשׁוּבָה, שֶׁזֶּה בְּחִינַת "וַאֲנִי יָדַי מְלֻכְלָכוֹת בְּדָם וּבְשָׁפִיר וְכוּ' כְּדֵי לְטַהֵר וְכוּ'", וּבְכֹחַ אֵלּוּ הַצַּדִּיקִים יֵשׁ תִּקְוָה לְכָל מִי שֶׁיֹּאחַז בָּהֶם, שֶׁיַּעֲלֶה מֵעֹמֶק יְרִידָתוֹ לַעֲלִיָּה גְדוֹלָה, וְשֶׁיִּהְיוּ נַעֲשִׂים עַל־יְדֵי־זֶה דַּיְקָא כֵּלִים נִפְלָאִים לְקַבֵּל אוֹר הָאֵין־סוֹף כָּרָאוּי. רַק הָעִקָּר שֶׁיִּשְׁמַע לְדִבְרֵיהֶם וְיֵלֵךְ בְּדַרְכֵיהֶם מֵעַתָּה עַל־כָּל־פָּנִים, וִיסַלֵּק חָכְמָתוֹ כְּאִלּוּ אֵין לוֹ שׁוּם שֵׂכֶל, רַק יְבַטֵּל דַּעְתּוֹ לְגַמְרֵי נֶגְדָּם, וְאָז יִזְכֶּה בְּוַדַּ
